// The PC launcher asks for a confirmation password and an optional QQ number.
// Keep the same account rules as the registration protocol, then reuse the
// normal cross-play request so a successful registration logs straight in.
let bridgeRegister58Busy=false;
function bridgeRegister58(){
 if(loggingIn107||bridgeRegister58Busy||document.querySelector('.bridgeRegisterOverlay58'))return;
 const zone=document.getElementById('serverZone');
 if(!zone?.value){$('loginError').textContent='请先选择区服';return;}
 const overlay=document.createElement('section');overlay.className='bridgeRegisterOverlay58';
 overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','注册账号');
 const card=document.createElement('form');card.className='bridgeRegisterCard58';
 card.innerHTML='<header class="bridgeRegisterHeader58"><h2>注册账号</h2><p class="bridgeRegisterZone58"></p></header><label>账号<input name="account" autocomplete="username" maxlength="31" required></label>'+
  '<label>密码<input name="password" type="password" autocomplete="new-password" maxlength="16" required></label>'+
  '<label>确认密码<input name="confirm" type="password" autocomplete="new-password" maxlength="16" required></label>'+
  '<label>QQ号（可选）<input name="qq" inputmode="numeric" autocomplete="off" maxlength="32" placeholder="用于找回密码"></label>'+
  '<p class="bridgeRegisterHint58">账号 6-31 位，以字母开头、字母或数字结尾，中间可用下划线。密码 1-16 位，使用英文字母、数字或符号。</p>'+
  '<p class="bridgeRegisterMessage58" role="alert"></p><div class="bridgeRegisterButtons58"><button type="button" data-cancel>取消</button><button type="submit">注册并进入</button></div>';
 overlay.append(card);document.body.append(overlay);
 card.querySelector('.bridgeRegisterZone58').textContent='区服：'+zone.selectedOptions[0].textContent;
 const account=card.elements.account,password=card.elements.password,confirm=card.elements.confirm,qq=card.elements.qq,
  message=card.querySelector('.bridgeRegisterMessage58'),buttons=[...card.querySelectorAll('button')];
 const loginForm=$('loginForm'),wasInert=loginForm.inert;loginForm.inert=true;
 const close=()=>{password.value='';confirm.value='';loginForm.inert=wasInert;if(overlay.isConnected)overlay.remove();$('register').focus();};
 card.querySelector('[data-cancel]').onclick=()=>{if(!bridgeRegister58Busy)close();};
 overlay.onkeydown=event=>{if(event.key==='Escape'&&!bridgeRegister58Busy)close();};
 card.onsubmit=async event=>{
  event.preventDefault();if(bridgeRegister58Busy)return;
  const user=account.value.trim(),secret=password.value,again=confirm.value,qqText=qq.value.trim();
  if(!/^[a-zA-Z][a-zA-Z0-9_]{4,29}[a-zA-Z0-9]$/.test(user)){message.textContent='账号需6-31位，以字母开头、字母或数字结尾，中间可用下划线';account.focus();return;}
  if(!/^[\x21-\x7e]{1,16}$/.test(secret)){message.textContent='密码需1-16位英文字母、数字或符号，不含空格';password.focus();return;}
  if(secret!==again){message.textContent='两次输入密码不一致';confirm.focus();return;}
  if(qqText&&!/^\d{5,}$/.test(qqText)){message.textContent='QQ号只能为数字，且不能少于5位';qq.focus();return;}
  bridgeRegister58Busy=true;buttons.forEach(button=>button.disabled=true);message.textContent='正在注册…';
  try{await serverReady107;const result=await request('/register',{user,password:secret,qq:qqText});
   if(result?.ok!==true)throw Error('注册结果尚未确认，请使用该账号登录核对');
   $('user').value=user;$('password').value=secret;close();
   await login();if(phase==='login')$('loginError').textContent='账号已注册成功。'+($('loginError').textContent||'请登录');
  }catch(error){message.textContent=error?.message||'注册失败，请稍后重试';}
  finally{bridgeRegister58Busy=false;buttons.forEach(button=>button.disabled=false);}
 };
 account.focus();
}

