// NPC formatting is parsed by the bridge. Render only verified text/color runs,
// never script markup or HTML from a realm response.
function bridgeNpcText114(node,text,runs){
 const plain=typeof text==='string'?text:'';
 const valid=Array.isArray(runs)&&runs.length>0&&runs.length<=4096&&
  runs.every(run=>run&&typeof run==='object'&&!Array.isArray(run)&&
   typeof run.text==='string'&&(run.color===undefined||
    typeof run.color==='string'&&/^#(?:[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(run.color)))&&
  runs.map(run=>run.text).join('')===plain;
 node.style.whiteSpace='pre-wrap';
 if(!valid){node.replaceChildren(plain);return node;}
 const doc=node.ownerDocument;
 node.replaceChildren(...runs.map(run=>{
  if(run.color===undefined)return doc.createTextNode(run.text);
  const span=doc.createElement('span');span.textContent=run.text;
  span.style.color=run.color;return span;
 }));
 return node;
}

