// Only the native, click-bound gather state owns this bar. Elapsed time never
// completes a task, sends another click, or starts a new automatic gather.
let bridgeGatherView114=null,bridgeGatherBusy114=null,bridgeGatherNotices114=new Set();
function bridgeGatherLive114(frame=world){
 const g=state?.gather;
 return phase==='game'&&state?.meta?.bridge==='pc6020'&&frame?.meta?.bridge==='pc6020'&&
  g?.characterId===state?.character?.id&&g.sceneToken===frame.sceneToken&&
  g.mapId===frame.map?.id&&g.instanceId===frame.map?.instanceId?g:null;
}
function bridgeGatherChoice114(n){
 if(phase!=='game'||state?.meta?.bridge!=='pc6020'||!n||n.npcType!==26||n.camp!==0||n.dead||
    !Number.isSafeInteger(n.uid??n.id)||(n.uid??n.id)<=0||world?.map?.id!==state?.position?.map)return null;
 const live=world.npcs?.find(row=>(row.uid??row.id)===(n.uid??n.id));
 if(live!==n)return null;
 for(const {meta,record,status} of bridgeQuestRecords114(state)){
  if(status!==1||record.full!==true||record.variables?.state!==1)continue;
  const target=meta.sceneTargets?.find(t=>t.npcId===n.template&&t.npcType===26&&t.camp===0);
  if(!target)continue;
  if(target.progressVars.some(key=>{const goal=meta.goals?.find(g=>g.progressVar===key),value=record.variables?.[key]??0;
   return goal&&Number.isInteger(value)&&value>=0&&value<goal.count;}))return {questId:meta.questId,npcId:n.uid??n.id,verb:meta.verb};
 }
 return null;
}
async function bridgeOpenGather114(n){
 const owner=`${epoch}:${state?.character?.id}`,choice=bridgeGatherChoice114(n);
 if(!choice){toast('当前任务不需要这个采集目标');return;}
 if(!bridgeNpcInRange114(n)){toast('请靠近目标后'+choice.verb);return;}
 if(bridgeGatherBusy114===owner)return;
 const g=bridgeGatherLive114();
 if(g&&['awaiting','progress','unknown'].includes(g.status)){toast(g.message||'正在等待本次采集结果');return;}
 bridgeGatherBusy114=owner;
 try{await mutate({type:'quest_gather',questId:choice.questId,npcId:choice.npcId});}
 catch(failure){if(`${epoch}:${state?.character?.id}`===owner)toast(failure?.message||'采集结果尚未确认，请核对任务进度');}
 finally{if(bridgeGatherBusy114===owner)bridgeGatherBusy114=null;}
}
function bridgeGatherClear114(){
 const view=bridgeGatherView114;bridgeGatherView114=null;
 if(view){cancelAnimationFrame(view.raf);view.root.remove();}
}
function bridgeGatherObserve114(frame=world){
 const g=bridgeGatherLive114(frame);
 if(!g||!['awaiting','progress','unknown'].includes(g.status)){
  bridgeGatherClear114();
  if(g&&['confirmed','interrupted'].includes(g.status)){
   const key=[epoch,g.characterId,g.sceneToken,g.revision,g.status].join(':');
   if(!bridgeGatherNotices114.has(key)){bridgeGatherNotices114.add(key);
    if(bridgeGatherNotices114.size>128)bridgeGatherNotices114=new Set([key]);
    toast(g.message||(g.status==='confirmed'?'任务进度已更新':'采集已中断'));}
  }
  return;
 }
 const key=[epoch,g.characterId,g.sceneToken,g.questId,g.npcId].join(':');
 if(bridgeGatherView114?.key!==key){
  bridgeGatherClear114();
  const root=el('section',undefined,'bridgeGather114'),label=el('p'),bar=el('div',undefined,'bridgeGatherBar114'),fill=el('i');
  root.setAttribute('role','status');root.setAttribute('aria-live','polite');
  bar.setAttribute('role','progressbar');bar.setAttribute('aria-label','采集进度');
  bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax','2000');bar.append(fill);root.append(label,bar);
  document.body.append(root);bridgeGatherView114={key,root,label,bar,fill,epoch,owner:g.characterId,raf:0};
  const draw=()=>{const view=bridgeGatherView114;if(!view||view.key!==key)return;
   const live=bridgeGatherLive114();
   if(view.epoch!==epoch||!live||!['awaiting','progress','unknown'].includes(live.status)){bridgeGatherObserve114();return;}
   // The 2000 ms duration is the audited native task-gather constant. Only a
   // correctly bound 1a/01 receipt supplies the remaining countdown.
   const counting=live.status==='progress'&&Number.isFinite(live.remainingMs)&&Number.isFinite(live.receivedAt),
    remaining=counting?Math.max(0,live.remainingMs-Math.max(0,Date.now()-live.receivedAt)):null,
    elapsed=remaining===null?0:Math.max(0,Math.min(2000,2000-remaining));
   view.root.dataset.status=live.status;view.bar.hidden=!counting;
   view.bar.setAttribute('aria-valuenow',String(elapsed));view.fill.style.width=`${elapsed/20}%`;
   view.label.textContent=live.status==='unknown'?(live.message||'采集结果未确认，请核对任务进度'):
    live.status==='awaiting'?'正在等待采集开始':remaining>0?(live.text||'采集中'):'正在等待采集结果';
   view.raf=requestAnimationFrame(draw);
  };draw();
 }
}

