   label.append(input);detail.append(el('p','每件 '+row.unitPrice.toLocaleString('zh-CN')+' 金币'),label,total);const a=action();total.textContent=a?'合计 '+a.expectedCost.toLocaleString('zh-CN')+' 金币':'数量或金币余额不符合要求';
