  card.append(el('h3','确认'+bridgeMoyangTitles114[c.service]),el('p',c.service==='compose'?'主装备：'+(feed().items?.find(row=>row.instanceId===c.slots[5])?.name||'未报告'):(selected()?.name||'未报告')+(c.service==='materials'?' ×'+a.quantity:'')),
   el('p','本次费用：'+a.expectedCost.toLocaleString('zh-CN')+' 金币'),el('p','材料：'+(c.service==='compose'?c.slots.slice(0,5).filter(Boolean).map(id=>feed().items?.find(row=>row.instanceId===id)?.name||'未报告').join('、'):materialText(selected()?.materials))),
   el('p',warning,'bridgeMoyangWarning114'));
