  let message=c.message||v.message;
  if(!sceneCurrent())message=v.pending||c.write?v.message||'地图已变化，购买结果尚未确认；请核对背包和余额':'地图已变化，请重新选择摊位招牌';
  else if(waiting(v.pending)||c.write)message=v.message||'购买请求已提交，区服数据稍后更新';
  else if(c.reading||v.queryPending)message='正在读取摊位商品…';
