  setTimeout(()=>{if(submitSerial49===serial){submitted=false;if(bridgeNpcItemPending114===pending)bridgeNpcItemPending114=null;if(alive())update(true);}},800);
  try{await mutate({type,npcId,instanceId:selected.instanceId,expectedCount:selected.count,contextToken});}
  catch(error){if(alive())toast(error?.message||'仓库操作未完成');}
  finally{if(bridgeNpcItemPending114===pending)bridgeNpcItemPending114=null;if(submitSerial49===serial)submitted=false;if(alive())update(true);}
