  const talent=bridgeTalents114.talents[String(id)];
  return {...talent,image:bridgeTalents114.icons[String(talent.icon)],
   syncedStatus:skills.some(skill=>Number(skill?.id)===talent.statusId&&Number.isFinite(Number(skill?.level)))};
