function bridgeParentQuestText114(q){
 const progress=Number.isInteger(q.progress)?`${q.progress}/${q.targetCount}`:`与${q.npcName}交谈查看考验任务`;
 return `${q.title}${q.perfect?'（完美通过）':q.reply?'（通过）':''}\n完成：${q.objective} ${progress}`+
  (q.reply?`\n回复：${q.npcName}`:'');
}
function bridgeGoParentQuest114(questId){
 const q=bridgeParentQuestChoice114(state,questId);if(!q)return;
 bridgeGoNpcQuest114(q,'parent');
}
function bridgeGoGuideQuest114(questId){
 const q=bridgeGuideQuestChoice114(state,questId);if(!q)return;
 bridgeGoNpcQuest114(q,'guide');
}
function bridgeGoNpcQuest114(q,kind){
 bridgeParentTravel114=null;
 if(state.dungeons?.inside===true){
  toast('请先离开副本，返回'+q.mapName+'，'+(kind==='parent'?'回复':'拜访')+q.npcName+`（${q.x},${q.y}）`);render('quests');return;
 }
 const n=world?.npcs?.find(n=>n.template===q.npcId);
 if(q.mapId===state.position?.map&&bridgeNpcInRange114(n)){openNpc(n.id??n.uid).catch(error);return;}
 const route=bridgeQuestRoute114(q,kind),cross=q.mapId!==state.position?.map;
 if(cross&&(!route||route.row.reason||!route.row.hops?.length)){
  toast(route?.row.reason||'前往'+q.mapName+'，拜访'+q.npcName+'的跨地图通路尚未报告，请稍后再试。');render('quests');return;
 }
 const t={questId:q.questId,kind,owner:state.character?.id,epoch,inputGeneration:state.inputGeneration,
  map:q.mapId,targetKey:bridgeQuestTargetKey114(q,kind),stageToken:route?.row.stageToken,
  correction:world?.positionCorrection?.seq,leg:null,cross};
 bridgeParentTravel114=t;
 if(cross){
  const hop=route.row.hops[0];
  if(hop.mapId!==state.position.map||!Number.isInteger(hop.targetMapId)||![hop.x,hop.y].every(Number.isInteger)){
   bridgeQuestTravelCancel114('当前地图出口资料无效，请重新前往。');return;
  }
  if(bridgeQuestTravelSend114(t,{kind:'navigate_point',x:hop.x,y:hop.y},hop))close();
 }else if(bridgeQuestTravelFinal114(t,q))close();
}
function bridgeQuestTravelFinal114(t,q){
 if(!bridgeQuestTravelSend114(t,{kind:'quest_track',questId:t.questId}))return false;
 if(t.kind==='story'&&q.kind==='region')t.dungeonTravel=bridgeDungeonTravel114={id:q.instanceId,owner:t.owner,
  map:q.mapId,started:Date.now(),offerToken:state.dungeons?.offer?.token};
 return true;
}
function bridgeParentArrival114(){
 const t=bridgeParentTravel114;if(!t)return;
 if(!bridgeQuestTravelCurrent114(t)){bridgeQuestTravelCancel114();return;}
 if(typeof dir!=='undefined'&&Math.hypot(dir?.x||0,dir?.z||0)>.001){bridgeQuestTravelCancel114();return;}
 if(state.dungeons?.inside===true){bridgeQuestTravelCancel114();return;}
 const q=bridgeQuestTravelTarget114(t.kind,t.questId);
 if(!q||bridgeQuestTargetKey114(q,t.kind)!==t.targetKey){bridgeQuestTravelCancel114();return;}
 const leg=t.leg;if(!leg)return;
 if(state.position?.map!==leg.mapId){
  if(state.position?.map!==leg.targetMapId){bridgeQuestTravelCancel114('已进入其他地图，任务寻路已停止。');return;}
  const route=bridgeQuestRoute114(q,t.kind);
  // UI state and the actual world must both reflect the native new scene.
  // An old route feed never starts the following leg, even after HTTP200.
  if(!route||!leg.accepted||route.feed.generation<=leg.sceneGeneration)return;
  if(route.row.stageToken!==t.stageToken||JSON.stringify([route.feed.generation,route.feed.sceneToken])===leg.scope){bridgeQuestTravelCancel114();return;}
  if(route.row.reason){bridgeQuestTravelCancel114(route.row.reason);return;}
  if(q.mapId===state.position.map){t.correction=world?.positionCorrection?.seq;bridgeQuestTravelFinal114(t,q);}
  else{
   const hop=route.row.hops?.[0];
   if(hop?.mapId!==state.position.map||!Number.isInteger(hop.targetMapId)||![hop.x,hop.y].every(Number.isInteger)){
    bridgeQuestTravelCancel114('当前地图出口资料无效，请重新前往。');return;
   }
   t.correction=world?.positionCorrection?.seq;
   bridgeQuestTravelSend114(t,{kind:'navigate_point',x:hop.x,y:hop.y},hop);
  }
  return;
 }
 if(world?.positionCorrection&&world.positionCorrection.seq!==t.correction){bridgeQuestTravelCancel114();return;}
 if(leg.scope&&state.questRoutes?.mapId===leg.mapId&&
  JSON.stringify([state.questRoutes.generation,state.questRoutes.sceneToken])!==leg.scope){bridgeQuestTravelCancel114();return;}
 if(t.cross){const route=bridgeQuestRoute114(q,t.kind);
  if(route&&route.row.stageToken!==t.stageToken){bridgeQuestTravelCancel114();return;}}
 if(leg.action.kind!=='quest_track'||!leg.accepted)return;
 const n=world?.npcs?.find(n=>n.template===q.npcId);
 if(q.kind!=='region'&&bridgeNpcInRange114(n)){bridgeParentTravel114=null;openNpc(n.id??n.uid).catch(error);}
}
function bridgeAwardQuest114(questId){
 if(bridgeQuestAwardPending114!==null)return;
 const owner=state.character?.id,generation=epoch;
 bridgeQuestAwardPending114=questId;
 void mutate({type:'quest_award',questId}).then(result=>{
  if(epoch===generation&&state.character?.id===owner)
   toast(result?.message||'交付请求已发送，请刷新任务核对');
 }).catch(error).finally(()=>{
  if(bridgeQuestAwardPending114===questId)bridgeQuestAwardPending114=null;
 });
}
function bridgeOpenQuestTab114(tab){
 bridgeQuestOwner114=state.character?.id;bridgeQuestTab114=tab;render('quests');
}
function bridgeGoStory114(questId=null){
 if(state.dungeons?.inside===true)return;
 // Some direct-session snapshots omit the optional capability bit while the
 // native quest target is already present. Only an explicit server-side false
 // disables tracking; an unknown bit must not turn the button into a no-op.
 if(state.meta?.quests?.track===false){toast('区服暂时禁止任务寻路，请稍后刷新任务');return;}
 const targets=state.storyTargets??[];
 if(questId!==null&&!targets.some(q=>q.questId===questId)&&
    !bridgeQuestRecords114(state).some(q=>q.meta.questId===questId))return;
 const target=questId===null?targets[0]:targets.find(q=>q.questId===questId);
 if(!target){toast('尚未读取到当前剧情任务的入口 NPC');return;}
 // Follow the PC quest link, never the monster position or quest giver.
 bridgeGoNpcQuest114(target,'story');
}
function bridgeQuests114(body){
 if(bridgeQuestOwner114!==state.character?.id){bridgeQuestOwner114=state.character?.id;bridgeQuestTab114='current';}
 body.classList.add('bridgeQuestPanel114');
 const tabs=el('nav',undefined,'tabs109 bridgeQuestTabs114');tabs.setAttribute('role','tablist');
 for(const [key,label] of [['current','当前任务'],['chapters','世界篇章'],['dungeons','传奇副本']]){
  const tab=button(label,()=>bridgeOpenQuestTab114(key));
  tab.setAttribute('role','tab');tab.setAttribute('aria-selected',String(key===bridgeQuestTab114));
  if(key===bridgeQuestTab114)tab.className='selected109';tabs.append(tab);
 }
 body.append(tabs);
 if(bridgeQuestTab114==='chapters'){bridgeChapters114(body).catch(error);return;}
 if(bridgeQuestTab114==='dungeons'){bridgeDungeons114(body,'legendary');return;}
 const targets=state.storyTargets??[],parents=bridgeParentQuests114(state),guides=bridgeGuideQuests114(state),display=bridgeDisplayQuests114(state);
 const sceneInstanceId=Number(state.map?.instanceId??state.map?.instanceid??world?.map?.instanceId??0);
 const inside=state.dungeons?.inside===true||state.preferences?.instance===true||sceneInstanceId>0;
 for(const q of guides)body.append(row(q.title,
  `${q.objective}\n${q.npcName} · ${q.mapName}（${q.x},${q.y}）`,
  button('拜访 '+q.npcName,()=>bridgeGoGuideQuest114(q.questId)),
  ...inside&&q.mapId!==state.position?.map?[button('离开副本',()=>mutate({type:'dungeon_leave'}))]:[]));
 for(const q of parents){
  const progress=Number.isInteger(q.progress)?`${q.progress}/${q.targetCount}`:'进度待同步';
  body.append(row(q.title+(q.perfect?'（完美通过）':q.reply?'（通过）':''),
   `完成：${q.objective} ${progress}\n${q.reply?'回复':'历练 NPC'}：${q.npcName} · ${q.mapName}（${q.x},${q.y}）`,
   button((q.reply?'回复':'前往')+' '+q.npcName,()=>bridgeGoParentQuest114(q.questId)),
   ...inside&&q.mapId!==state.position?.map?[button('离开副本',()=>mutate({type:'dungeon_leave'}))]:[]));
 }
 for(const q of display)body.append(row(q.title,q.objective,
  ...q.visit?[button('前往 '+q.visit.npcName,()=>bridgeGoDisplayQuest114(q.questId))]:[],
  ...!q.visit&&!inside&&targets.some(t=>t.questId===q.questId)?[button('前往入口',()=>bridgeGoDisplayQuest114(q.questId))]:[],
  ...inside&&q.visit&&q.visit.mapId!==state.position?.map?[button('离开副本',()=>mutate({type:'dungeon_leave'}))]:[]));
 const grouped=new Map();
 for(const q of targets){const key=[q.instanceId??q.dungeonId,q.mapId,q.x,q.y].join(':');
  if(!grouped.has(key))grouped.set(key,q);}
 for(const q of grouped.values())body.append(row('剧情副本 · '+q.name,`${q.mapName} (${q.x},${q.y})`,
  ...inside?[]:[button('进入剧情副本',()=>bridgeGoStory114(q.questId))]));
 if(inside)
  body.append(row('副本进行中','完成当前副本或返回副本入口后继续任务。',
   button('离开副本',()=>mutate({type:'dungeon_leave'}))));
 if(!targets.length&&!inside&&!parents.length&&!guides.length&&!display.length)body.append(row('剧情副本（普通）','当前剧情任务的入口 NPC 尚未同步。',
  button('进入剧情副本',()=>bridgeGoStory114(),true)));
 const verified=bridgeQuestRecords114(state);
 if(bridgeMissing114('quests')&&!verified.length&&!parents.length&&!guides.length&&!display.length){body.append(el('p','任务记录正在读取。'));return;}
 for(const {meta,record,status} of verified){
  const canAward=status===-3&&record.full===true;
  body.append(row(`${status===-3?'可交付':'进行中'} · ${meta.title}`,bridgeQuestObjective114(meta,record,status),
   ...(status===-3?[button('交付任务',()=>bridgeGoQuest114(meta.questId),
    !canAward||bridgeQuestAwardPending114!==null)]:
    inside?[]:[button('前往入口',()=>bridgeGoQuest114(meta.questId),
     !targets.some(t=>t.questId===meta.questId))])));
 }
 if(!verified.length&&!targets.length&&!parents.length&&!guides.length&&!display.length)body.append(el('p','尚未读取到可显示的当前任务。'));
 body.append(el('p','区服确认完成的子任务可直接交付；指引和历练主线请拜访对应 NPC，在交谈中继续任务。'));
}

const bridgeInnerImages114={"neigongxinfaLV":"data:image/png;base64,","neigongwuxingLV":"data:image/png;base64,","neigongxinfaxuanfu":"data:image/png;base64,","neigongxinfataiyinNormal":"data:image/png;base64,","neigongxinfataiyinPushed":"data:image/png;base64,","neigongxinfashaoyinNormal":"data:image/png;base64,","neigongxinfashaoyinPushed":"data:image/png;base64,","neigongxinfashaoyangNormal":"data:image/png;base64,","neigongxinfashaoyangPushed":"data:image/png;base64,","neigongxinfataiyangNormal":"data:image/png;base64,","neigongxinfataiyangPushed":"data:image/png;base64,","neigongxinfazhonggongNormal":"data:image/png;base64,","neigongxinfazhonggongPushed":"data:image/png;base64,","neigongxinfaBACKbotton":"data:image/png;base64,","neigongxinfaBACK":"data:image/png;base64,","neigongxinfaputongNormal":"data:image/png;base64,","neigongxinfaxuanzhong":"data:image/png;base64,","neigongxinfaCenterHover":"data:image/png;base64,"};
let bridgeInnerPalace114=0,bridgeInnerBook114=null,bridgeInnerOwner114='',bridgeInnerBusy114=null;
function bridgeInner114(body){
 body.classList.add('bridgeInner114');
 const owner=state?.character?.id,generation=epoch,ownerKey=generation+':'+owner,opening={};
 body.bridgeInnerOpening114=opening;
 if(ownerKey!==bridgeInnerOwner114){bridgeInnerOwner114=ownerKey;bridgeInnerPalace114=0;bridgeInnerBook114=null;}
 const current=()=>phase==='game'&&epoch===generation&&state?.character?.id===owner&&menu==='growth'&&
  body.isConnected&&body.bridgeInnerOpening114===opening;
 const inner=state.inner??{},books=Array.isArray(inner.owned)?inner.owned:[];
 const selected=books.find(book=>book.id===bridgeInnerBook114)||books.find(book=>book.active)||books[0];
 if(selected)bridgeInnerBook114=selected.id;
 const busy=()=>!!state.inner?.pending||state.inner?.unknown===true||bridgeInnerBusy114?.ownerKey===ownerKey;
 // Original sprite keys invert the printed yin/yang labels. Match wire indices to visible text.
 const positions=[['中宫','zhonggong',50,51.5],['太阳','taiyin',50,18],
  ['太阴','taiyang',50.5,81.5],['少阳','shaoyin',17.5,51.5],['少阴','shaoyang',83,51]];
 const stage=el('section',undefined,'bridgeInnerStage114'),board=el('div',undefined,'bridgeInnerBoard114');
 board.style.backgroundImage='url("'+bridgeInnerImages114.neigongxinfaBACK+'")';stage.append(board);
 const side=el('aside',undefined,'bridgeInnerSide114'),effects=el('section',undefined,'bridgeInnerBox114'),
  detail=el('section',undefined,'bridgeInnerBox114'),footer=el('nav',undefined,'bridgeInnerBooks114');
 footer.style.backgroundImage='url("'+bridgeInnerImages114.neigongxinfaBACKbotton+'")';
 side.append(effects,detail);body.append(stage,side,footer);
 const amount=value=>value==null?'—':String(value);
 const lines=value=>Array.isArray(value)?value.filter(line=>typeof line==='string'):
  typeof value==='string'?[value]:[];
 const submit=async(operation,palace)=>{
  if(!current()||busy()||!selected)return;
  const live=state.inner?.owned?.find(book=>book.id===selected.id),part=live?.palaces?.find(p=>p.index===palace);
  if(!live)return;
  const enabled=operation==='upgrade'?part?.canUpgrade:operation==='activate'?live.canActivate:live.canDeactivate;
  if(enabled!==true){toast(operation==='upgrade'?(part?.upgradeReason||'当前不能升级'):(live.activationReason||'当前不能切换内功'));return;}
  const record={ownerKey};bridgeInnerBusy114=record;
  for(const b of body.querySelectorAll('button'))b.disabled=true;
  try{await mutate({type:'inner',operation,id:live.id,...(operation==='upgrade'?{palace}:{})});}
  catch(failure){if(epoch===generation&&state?.character?.id===owner)toast(failure?.message||'内功请求未完成，请刷新核对');}
  finally{
   if(bridgeInnerBusy114===record)bridgeInnerBusy114=null;
   if(epoch===generation&&state?.character?.id===owner&&menu==='growth')render('growth');
  }
 };
 const nodes=[];
 const choose=index=>{
  if(!current())return;bridgeInnerPalace114=index;
  positions.forEach((p,i)=>{
   nodes[i].style.backgroundImage='url("'+bridgeInnerImages114['neigongxinfa'+p[1]+(i===index?'Pushed':'Normal')]+'")';
   nodes[i].setAttribute('aria-pressed',String(i===index));
   nodes[i].querySelector('.bridgeInnerSelection114').hidden=i!==index;
  });
  effects.replaceChildren(el('h3',selected?.name||'内功'));
  if(!selected){
   effects.append(el('p',inner.observed===true?'尚未拥有心法。':'尚未收到内功信息。','bridgeInnerEffects114'),
    el('p','使用心法物品后，等待区服同步心法列表。'));
   detail.replaceChildren(el('h3',positions[index][0]),el('p','请选择已拥有的心法。'));
   return;
  }
  effects.append(el('p',selected.active?'当前生效中':'当前未激活','bridgeInnerEffects114'));
  const effectLines=lines(selected.effects);
  effects.append(el('p','心法基础效果'),el('p',effectLines.length?effectLines.join('\n'):'当前效果尚未同步','bridgeInnerEffects114'));
  effects.append(el('p','辅助加成由当前激活心法的中宫等级决定。'));
  if(inner.pending)effects.append(el('p','正在等待区服确认…'));
  else if(inner.unknown)effects.append(el('p',inner.lastResult?.reason||'操作结果未确认，请刷新核对。'));
  if(selected.activationReason)effects.append(el('p',selected.activationReason));
  effects.append(button(selected.active?'关闭内功':'激活内功',()=>submit(selected.active?'deactivate':'activate'),
   busy()||(selected.active?selected.canDeactivate:selected.canActivate)!==true));
  const palace=selected.palaces?.find(part=>part.index===index),level=palace?.level??selected.levels?.[index];
  detail.replaceChildren(el('h3',positions[index][0]),el('p','心法等级：'+amount(level),'bridgeInnerEffects114'));
  const ownEffects=lines(palace?.effects),nextEffects=lines(palace?.nextEffects);
  const costs=[];
  if(palace?.requiredLevel!=null)costs.push('需求等级：'+amount(palace.requiredLevel));
  if(palace?.requiredMainLevel!=null)costs.push('需求中宫等级：'+amount(palace.requiredMainLevel));
  costs.push('需要经验：'+amount(palace?.requiredHonor),'需要金币：'+amount(palace?.requiredGold));
  detail.append(el('p',costs.join('\n'),'bridgeInnerCosts114'));
  if(ownEffects.length)detail.append(el('p','基础效果：'+ownEffects.join('；'),'bridgeInnerEffects114'));
  if(nextEffects.length)detail.append(el('p','下一级基础效果：'+nextEffects.join('；'),'bridgeInnerEffects114'));
  if(palace?.upgradeReason)detail.append(el('p',palace.upgradeReason));
  detail.append(button('升级心法',()=>submit('upgrade',index),busy()||palace?.canUpgrade!==true));
 };
 positions.forEach((p,i)=>{
  const node=button('',()=>choose(i));node.className='bridgeInnerPalace114';
  node.style.left=p[2]+'%';node.style.top=p[3]+'%';node.setAttribute('aria-label',p[0]);
  const palace=selected?.palaces?.find(part=>part.index===i);
  node.append(el('span',amount(palace?.level??selected?.levels?.[i]),'bridgeInnerLevel114'));
  const selection=el('span',undefined,'bridgeInnerSelection114');
  selection.style.backgroundImage='url("'+bridgeInnerImages114[i===0?'neigongxinfaCenterHover':'neigongxinfaxuanzhong']+'")';
  selection.setAttribute('aria-hidden','true');node.append(selection);
  if(i===0&&selected?.active===true){
   const active=el('span',undefined,'bridgeInnerActivation114');
   active.style.backgroundImage='url("'+bridgeInnerImages114.neigongxinfaCenterHover+'")';
   active.setAttribute('aria-hidden','true');node.append(active);node.dataset.active='true';
  }
  nodes.push(node);board.append(node);
 });
 for(const book of books){
  const tab=button(book.name||'心法 #'+book.id,()=>{if(current()&&!busy()){bridgeInnerBook114=book.id;render('growth');}},busy());
  tab.className='bridgeInnerBookTab114'+(book.id===selected?.id?' selected109':'');
  tab.setAttribute('aria-pressed',String(book.id===selected?.id));
  if(book.active)tab.append(el('small','生效中'));
  footer.append(tab);
 }
 if(!books.length)footer.append(el('span',inner.observed===true?'暂无心法':'等待区服同步心法列表'));
 choose(bridgeInnerPalace114);
}

