// These rows are authoritative scene objects; never create a drop from a bag
// removal or remove a ground label just because a pickup request was sent.
let bridgeGroundPending114=null,bridgeNpcListKey114='';
function bridgeNearbyNpcs114(){
 return bridgeMapNpcRows114();
}
function bridgeNearbyPanel114(body){
 bridgeMapNpcsPanel114(body);
}
function bridgeGroundPickup114(id=null){
 if(state?.meta?.groundItems?.pickup!==true){toast('地面物品正在同步');return;}
 if(world?.player?.dead){toast('角色死亡时不能拾取');return;}
 const p=world?.player,drops=world?.drops??[];
 if(!p)return;
 const item=id==null?[...drops].sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0]:drops.find(n=>n.id===id);
 if(!item){toast('附近没有可拾取的物品');return;}
 if(bridgeGroundPending114?.id===item.id)return;
 if(typeof release==='function')release();
 const pending={id:item.id,owner:state.character.id,generation:epoch,map:world.map.id,
  x:item.x,y:item.z,started:Date.now(),submitted:false};
 if(p.x!==item.x||p.z!==item.z)act({kind:'navigate_point',x:item.x,y:item.z});
 bridgeGroundPending114=pending;bridgeGroundObserve114(world);
}
function bridgeGroundObserve114(w){
 const pending=bridgeGroundPending114;if(!pending)return;
 if(typeof dir!=='undefined'&&Math.hypot(dir.x??0,dir.z??0)>.05){bridgeGroundPending114=null;return;}
 if(pending.owner!==state?.character?.id||pending.generation!==epoch||pending.map!==w?.map?.id||w.player?.dead||Date.now()-pending.started>90000){
  bridgeGroundPending114=null;return;
 }
 const item=(w.drops??[]).find(n=>n.id===pending.id);
 if(!item){bridgeGroundPending114=null;
  if(pending.submitted&&typeof refreshState==='function')refreshState();
  return;
 }
 if(pending.submitted){
  if(Date.now()-pending.sentAt>5000){bridgeGroundPending114=null;toast('拾取结果尚未更新，请核对物品');}
  return;
 }
 if(w.player?.x!==item.x||w.player?.z!==item.z)return;
 pending.submitted=true;pending.sentAt=Date.now();
 void mutate({type:'ground_pickup',instanceId:item.id}).catch(failure=>{
  if(bridgeGroundPending114===pending){bridgeGroundPending114=null;toast(failure?.message||'拾取未成功');}
 });
}
function bridgeWorldUpdated114(w){
 if(w?.meta?.bridge!=='pc6020')return;
 for(const item of w.drops??[]){const icon=bridgeItemIcons114[String(item.baseId??item.template)];
  if(Number.isInteger(icon)&&icon>0)item.icon=`icons/${icon}.png`;
 }
 bridgeGroundObserve114(w);
 if(menu!=='npcs'){bridgeNpcListKey114='';return;}
 const key=bridgeMapNpcListKey114();
 if(key!==bridgeNpcListKey114){bridgeNpcListKey114=key;render('npcs');}
}

// Native 18/3b is a quest menu, not missing NPC dialogue.
function bridgeNpcQuests114(body,n,dialog,current){
 const list=el('div',undefined,'bridgeNpcQuestList114'),status=el('p'),refresh=button('重新读取任务',()=>{
  if(current())return openBridgeNpc114(body,n);
 });body.append(status,list,refresh);
 const labels={'-7':'条件未满足','-5':'可接取','1':'进行中','-3':'可交付','2':'已完成','-2':'已完成'};
 let busy=false;const awardAttempts=new Set();
 function draw(){
  if(!current())return;
  const live=state.npcQuestContext,actions=state.npcQuestStatus??{},same=live?.contextToken===dialog.contextToken,
   pending=actions.pending,last=actions.lastResult;
  status.textContent=pending?'正在核对任务接取结果…':last?.status==='unknown'?
   '任务接取结果未确认，请重新读取任务核对。':last?.status==='accepted'?'任务已接取。':
   dialog.mode!==0?'任务列表已读取。':'请选择要接取的任务。';
  list.replaceChildren();refresh.disabled=busy;
  for(const quest of dialog.quests??[]){
   const record=state.questData?.records?.find(r=>r.id===quest.questId),nativeState=record?.variables?.state,
    observed=[1,-3,2,-2].includes(nativeState)?nativeState:quest.state,
    row=el('section',undefined,'row'),text=el('div');
   text.append(el('b',quest.title||`任务 #${quest.questId}`),el('p',bridgeQuestObjective114(quest,record,observed)),
    el('small',(labels[String(observed)]||'任务状态 '+observed)+(quest.needLevel?` · ${quest.needLevel}级`:'')));
   row.append(text);
   if(observed===-5&&dialog.mode===0&&quest.title){
    const take=button('接取任务',async()=>{
     if(!current()||busy||state.npcQuestContext?.contextToken!==dialog.contextToken)return;
     busy=true;draw();
     try{await mutate({type:'npc_quest_accept',npcId:dialog.npcID,questId:quest.questId,contextToken:dialog.contextToken});}
     catch(failure){if(current())toast(failure?.message||'接取结果未确认，请重新读取任务核对。');}
     finally{busy=false;if(current())draw();}
    },busy||!!pending||!same);row.append(take);
   }
   if(observed===-3&&quest.finishState===-2&&[101,102,103].includes(quest.questType)){
    const award=button(awardAttempts.has(quest.questId)?'已请求交付':'交付任务',async()=>{
     if(!current()||busy||awardAttempts.has(quest.questId)||record?.full!==true||nativeState!==-3)return;
     awardAttempts.add(quest.questId);busy=true;draw();
     try{const result=await mutate({type:'quest_award',questId:quest.questId});if(current()&&result?.message)toast(result.message);}
     catch(failure){if(current())toast(failure?.message||'交付结果未确认，请重新读取任务核对。');}
     finally{busy=false;if(current())draw();}
    },busy||awardAttempts.has(quest.questId)||record?.full!==true||nativeState!==-3);row.append(award);
   }
   list.append(row);
  }
  if(!list.children.length)list.append(el('p','当前没有可接取的任务。'));
 }
 draw();const timer=setInterval(()=>{if(!current()){clearInterval(timer);return;}draw();},800);
 body.bridgeNpcQuestDispose114=()=>clearInterval(timer);
}

// Service evidence comes from PC replies. Never infer services from NPC names,
// the old mobile template IDs, or an empty (visibility-limited) scene list.
function pcNpcItemContext114(kind,s=state,w=world){
 const label=kind==='warehouse'?'仓库':'商人';
 const unavailable=reason=>({status:'unavailable',npcId:null,npc:null,reason});
 if(!['warehouse','merchant'].includes(kind))return unavailable('物品服务类型无效');
 if(!s?.character?.id)return unavailable('角色尚未进入游戏');
 if(!Array.isArray(s.npcItemServices))return {status:'pending',npcId:null,npc:null,reason:`${label}服务信息尚未同步`};
 const stateMap=s.position?.map??s.map?.id;
 if(w&&w.map?.id!==stateMap)return {status:'pending',npcId:null,npc:null,reason:'当前地图信息正在同步'};
 const player=w?.player??s.position,npcs=w? w.npcs:s.npcs;
 if(!player||!Array.isArray(npcs))return {status:'pending',npcId:null,npc:null,reason:'附近 NPC 信息尚未同步'};
 if(player.dead)return unavailable('倒地时不能使用物品服务');
 const services=s.npcItemServices.filter(row=>row?.kind===kind&&
  Number.isInteger(row.uid)&&row.uid>0&&row.uid<=0xffffffff);
 const serviceIds=new Set(services.map(row=>row.uid));
 const candidates=npcs.filter(n=>serviceIds.has(n.uid??n.id)&&n.camp===0&&!n.dead&&n.alive!==false&&
  !n.guideArrow&&n.interactable!==false&&[n.x,n.z??n.y,player.x,player.z??player.y].every(Number.isFinite))
  .map(n=>({npc:n,distance:Math.max(Math.abs(n.x-player.x),Math.abs((n.z??n.y)-(player.z??player.y)))}))
  .sort((a,b)=>a.distance-b.distance||(a.npc.uid??a.npc.id)-(b.npc.uid??b.npc.id));
 const chosen=candidates.find(row=>pcNpcInRange114(row.npc,player))??candidates[0];
 if(!chosen)return unavailable(kind==='warehouse'?'请先靠近仓库管理员并打开仓库':'请先靠近商人并打开商店');
 const npc=chosen.npc,inRange=pcNpcInRange114(npc,player),service=services.find(row=>row.uid===(npc.uid??npc.id));
 return {status:inRange?'ready':'far',npcId:npc.uid??npc.id,npc,service,distance:chosen.distance,
  reason:inRange?'':`请靠近${npc.name||label}后${kind==='warehouse'?'存入仓库':'出售物品'}`};
}
let bridgeNpcItemPending114=null;
function bridgeNpcItemWaiting114(kind,instanceId){
 if(bridgeNpcItemPending114?.expiresAt<=Date.now())bridgeNpcItemPending114=null;
 return !!bridgeNpcItemPending114&&bridgeNpcItemPending114.owner===state?.character?.id&&
  bridgeNpcItemPending114.generation===epoch&&(!kind||bridgeNpcItemPending114.kind===kind)&&
  (instanceId===undefined||bridgeNpcItemPending114.instanceId===instanceId);
}
function bridgeNpcItemWait114(){
 return '';
}
function bridgeNpcItemActions114(actions,item,options){
 const owner=state?.character?.id,generation=epoch,instanceId=Number(item.instanceId);
 const current=()=>actions.isConnected&&epoch===generation&&state?.character?.id===owner&&options.current();
 const liveItem=()=>options.liveItem?options.liveItem():
  (state.inventory??[]).find(row=>Number(row.instanceId)===instanceId&&Number(row.baseId)===Number(item.baseId));
 const expectedOf=fresh=>Object.fromEntries(['instanceId','baseId','packId','slot','count'].map(key=>[key,Number(fresh[key])]));
 const sameItem=(fresh,expected)=>fresh&&Object.entries(expected).every(([key,value])=>Number(fresh[key])===value);
 let overlay=null,confirmation=null,timer=null,disposed=false;
 const blocked=(kind,fresh)=>{
  if(!fresh||Number(fresh.packId)!==1||!['instanceId','baseId','count'].every(key=>
   Number.isInteger(Number(fresh[key]))&&Number(fresh[key])>0&&Number(fresh[key])<=0xffffffff)||
   !Number.isInteger(Number(fresh.slot))||Number(fresh.slot)<0||Number(fresh.slot)>0xffff)return '物品已变化，请重新选择';
  if(bridgeNpcItemWaiting114(kind,instanceId))return '请求已提交，物品由区服更新';
  const nativePending=kind==='merchant'?state.npcSellStatus?.pending:state.warehousePending;
  if(Array.isArray(nativePending)&&nativePending.some(p=>p.instanceId===instanceId&&
   Number.isFinite(p.expiresAt)&&Date.now()<p.expiresAt))return '请求已提交，物品由区服更新';
  const extra=options.blocked?.(kind,fresh);if(extra)return extra;
  if(typeof options[kind==='warehouse'?'store':'sell']!=='function')return '此物品操作尚未接入';
  if(kind==='merchant'&&fresh.sell?.canSell!==true)return fresh.sell?.reason||'出售状态尚未同步';
  return '';
 };
 const dismiss=()=>{if(overlay){overlay.remove();overlay=null;}confirmation=null;};
 const notify=reason=>{if(current()&&reason)toast(reason);};
 const submit=async(kind,expected,selectedNpc,contextToken)=>{
  if(!current())return;
  const fresh=liveItem(),context=pcNpcItemContext114(kind),reason=blocked(kind,fresh);
  if(context.npcId===selectedNpc&&context.service?.contextToken!==contextToken){
   dismiss();notify(kind==='merchant'?'商店信息已变化，请重新确认':'仓库信息已变化，请重新确认');update();return;
  }
  if(!sameItem(fresh,expected)||reason||context.status!=='ready'||context.npcId!==selectedNpc){
   dismiss();notify(reason||context.reason||'物品或 NPC 已变化，请重新选择');update();return;
  }
  dismiss();const pending={owner,generation,kind,instanceId,expiresAt:Date.now()+800};bridgeNpcItemPending114=pending;update();
  setTimeout(()=>{if(bridgeNpcItemPending114===pending){bridgeNpcItemPending114=null;if(current())update();}},800);
  try{await options[kind==='warehouse'?'store':'sell']({item:fresh,npcId:context.npcId,expectedCount:expected.count,contextToken});}
  catch(failure){notify(failure?.message||'物品操作未完成');}
  finally{
   if(bridgeNpcItemPending114===pending)bridgeNpcItemPending114=null;
   if(current()){update();options.refresh?.();}
  }
 };
 const begin=kind=>{
  if(!current()||overlay)return;
  const fresh=liveItem(),context=pcNpcItemContext114(kind),reason=blocked(kind,fresh);
  if(reason||context.status!=='ready'){notify(reason||context.reason);update();return;}
  const expected=expectedOf(fresh),contextToken=context.service?.contextToken;
  if(kind==='warehouse')return submit(kind,expected,context.npcId,contextToken);
  const dialog=el('section',undefined,'bridgeStudyConfirm114'),heading=el('div',undefined,'panelhead'),
   content=el('div',undefined,'bridgeStudyConfirmBody114'),buttons=el('div',undefined,'buttons');
  overlay=el('div',undefined,'bridgeStudyOverlay114');confirmation=overlay;
  const opening=overlay,cancel=button('取消',dismiss),closeButton=button('×',dismiss);
  closeButton.setAttribute('aria-label','关闭出售确认');heading.append(el('h2','确认出售'),closeButton);
  dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label','确认出售物品');
  content.append(el('p',`向${context.npc.name||'商人'}出售「${fresh.name||'物品'}」整组 ${expected.count} 件？`));
  const confirm=button('确认出售',()=>{
   if(overlay!==opening||confirmation!==opening)return;
   return submit(kind,expected,context.npcId,contextToken);
  });
  buttons.append(cancel,confirm);content.append(buttons);dialog.append(heading,content);overlay.append(dialog);
  overlay.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();dismiss();}};
  overlay.onpointerdown=event=>event.stopPropagation();
  (options.body??actions).append(overlay);cancel.focus?.();
 };
 const store=button('存入仓库',()=>begin('warehouse'),true),sell=button('向商人出售',()=>begin('merchant'),true);
 const update=(initial=false)=>{
  if(disposed)return;
  if(!current()){if(initial&&!actions.isConnected)return;dispose();return;}
  const fresh=liveItem();
  for(const [kind,node] of [['warehouse',store],['merchant',sell]]){
   const context=pcNpcItemContext114(kind),itemReason=blocked(kind,fresh);
   node.disabled=!!itemReason||context.status==='pending';node.title=itemReason||context.reason;
   node.setAttribute('aria-busy',String(bridgeNpcItemWaiting114()));
  }
  sell.textContent=`向商人出售${Number(fresh?.count)>0?Number(fresh.count):''}件`;
 };
 const dispose=()=>{disposed=true;if(timer!==null)clearTimeout(timer);timer=null;dismiss();};
 const poll=()=>{update();if(!disposed)timer=setTimeout(poll,200);};
 actions.append(store,sell);update(true);if(!disposed)timer=setTimeout(poll,200);
 return {store,sell,update,dispose};
}

