  if(!current())return;
  const after=bridgeXianLingAccess114();if(!after.enabled)throw Error(after.reason);
  const catalogue=result.catalogue;
  if(!catalogue?.onlineCatalogue||!Array.isArray(catalogue.offers)||typeof catalogue.revision!=='string')
   throw Error('仙灵店铺商品尚未同步');
