// A long press opens a reviewed quantity window; it never buys on release.
let bridgeShopPress58=null,bridgeShopRelease58=null,bridgeShopPressBound58=false;
function bridgeShopLongPress58(element,callback){
 if(typeof document==='undefined'||typeof element?.addEventListener!=='function')return;
 if(!bridgeShopPressBound58){bridgeShopPressBound58=true;
  const finish=event=>{const p=bridgeShopPress58;if(!p||event.pointerId!==p.id)return;
   clearTimeout(p.timer);bridgeShopPress58=null;
   if(p.fired){bridgeShopRelease58={x:event.clientX,y:event.clientY,until:performance.now()+750};event.preventDefault();event.stopImmediatePropagation();}
  };
  document.addEventListener('pointerdown',event=>{bridgeShopRelease58=null;const p=bridgeShopPress58;if(p&&event.pointerId!==p.id){clearTimeout(p.timer);bridgeShopPress58=null;}},{capture:true});
  document.addEventListener('pointermove',event=>{const p=bridgeShopPress58;if(p&&event.pointerId===p.id&&Math.hypot(event.clientX-p.x,event.clientY-p.y)>10){clearTimeout(p.timer);if(!p.fired)bridgeShopPress58=null;}},{capture:true,passive:true});
  document.addEventListener('pointerup',finish,{capture:true});
  document.addEventListener('pointercancel',event=>{const p=bridgeShopPress58;if(p&&event.pointerId===p.id){clearTimeout(p.timer);bridgeShopPress58=null;}},{capture:true});
  document.addEventListener('click',event=>{const r=bridgeShopRelease58;
   if(event.detail!==0&&r&&performance.now()<r.until&&Math.hypot(event.clientX-r.x,event.clientY-r.y)<28){bridgeShopRelease58=null;event.preventDefault();event.stopImmediatePropagation();}
  },{capture:true});
 }
 element.addEventListener('pointerdown',event=>{
  if(event.button!==0||event.isPrimary===false)return;
  if(bridgeShopPress58){clearTimeout(bridgeShopPress58.timer);bridgeShopPress58=null;return;}
  const p={id:event.pointerId,x:event.clientX,y:event.clientY,fired:false,timer:null};bridgeShopPress58=p;
  p.timer=setTimeout(()=>{if(bridgeShopPress58!==p||!element.isConnected)return;p.fired=true;callback();},450);
 });
}

