   const reason=bridgeInventoryProblem114();if(reason){toast(reason);refresh();return;}
   if(!bridgeStallEligible114(fresh)||!Number.isSafeInteger(count)||count<1||count>fresh.count||!Number.isSafeInteger(value)||value<1||value>0xffffffff||
      (unitType===0&&count*value>0xffffffff)){toast('出售数量或价格无效，请重新填写');return;}
   const offer={instanceId:item.instanceId,count,price:value,unitType};
