 const target=assist?.enabled===true?find(assist.target):find(selected)||find(bridgeTargetConfirmed114);
 if(frame.player.dead){selected=0;bridgeTargetConfirmed114=0;root.hidden=true;return;}
 if(!target){root.hidden=true;return;}
