 parts.bar.setAttribute('role','progressbar');parts.bar.setAttribute('aria-label',`${target.name||'当前目标'}生命`);
 parts.bar.setAttribute('aria-valuemin','0');
 if(known){parts.bar.setAttribute('aria-valuenow',String(target.hp));parts.bar.setAttribute('aria-valuemax',String(target.maxHp));
  parts.bar.removeAttribute('aria-valuetext');}
 else{parts.bar.removeAttribute('aria-valuenow');parts.bar.removeAttribute('aria-valuemax');parts.bar.setAttribute('aria-valuetext','当前生命未报告');}
