function bridgeDungeonFeedback114(frame){
 if(frame?.meta?.bridge!=='pc6020'||!frame.player)return;
 const scene=JSON.stringify([frame.generation,frame.sceneToken,frame.map?.id,frame.map?.instanceId,frame.map?.country,frame.player.uid]);
 if(scene!==bridgeDungeonScene114){bridgeDungeonClear114();bridgeDungeonScene114=scene;}
 for(const event of frame.fullScreenAnimations||[]){
  if(event?.animationId!==128||event.source!=='09/03'||!event.id||bridgeDungeonSeen114.has(event.id)||
   !frame.map?.instanceId||event.sceneToken!==frame.sceneToken||event.mapId!==frame.map.id||event.instanceId!==frame.map.instanceId)continue;
  bridgeDungeonSeen114.add(event.id);bridgeDungeonFlowers114(event);
 }
 const present=new Set();
 for(const portal of frame.npcs||[]){
  if(!portal.portalEffect||portal.template!==60003)continue;
  const id=portal.id??portal.uid;present.add(id);
  const near=Math.hypot(frame.player.x-portal.x,frame.player.z-portal.z)<=1.5;
  const previous=bridgePortalNear114.get(id);bridgePortalNear114.set(id,{near,entered:previous?.entered||false});
  // The auto-battle exit planner already owns its requests. Manual entry is an
  // outside-to-inside transition, never a portal spawning under a still player.
  if(near&&previous&&!previous.near&&!previous.entered&&!frame.assist116?.enabled&&!frame.player.dead){
   bridgePortalNear114.get(id).entered=true;
   Promise.resolve().then(()=>openNpc(id)).catch(error);
  }
 }
 for(const id of bridgePortalNear114.keys())if(!present.has(id))bridgePortalNear114.delete(id);
}



// Still preview. Poll identity only: asynchronous native replacement can finish
// after the panel redraw, while unchanged models need no clone or render loop.
function bridgeFashionPreview114(host,source){
 let observed=null,copy=null,renderer=null,scene=null,camera=null,height=1,disposed=false;
 const releaseCopy=()=>{if(!copy)return;scene.remove(copy);const skeletons=new Set();copy.traverse(o=>{if(o.isSkinnedMesh&&o.skeleton)skeletons.add(o.skeleton);});for(const skeleton of skeletons)skeleton.dispose();copy=null;};
 const draw=()=>{if(disposed||!renderer||!copy)return;const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.top=height/2;camera.bottom=-height/2;camera.left=-height*w/h/2;camera.right=-camera.left;camera.updateProjectionMatrix();renderer.render(scene,camera);};
 const resize=new ResizeObserver(draw),observer=new MutationObserver(()=>{if(!host.isConnected)dispose();});
 const dispose=()=>{if(disposed)return;disposed=true;clearInterval(interval);resize.disconnect();observer.disconnect();releaseCopy();if(renderer){renderer.dispose();renderer.forceContextLoss();renderer.domElement.remove();}observed=null;};
 const poll=()=>{
  if(disposed)return;if(!host.isConnected){dispose();return;}
  const model=typeof source==='function'?source():source;
  if(!model){if(!copy)host.textContent='人物模型加载中…';return;}
  if(model===observed)return;
  const next=cloneNative107(model);
  if(!renderer){host.replaceChildren();renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(1);host.append(renderer.domElement);scene=new THREE.Scene();scene.add(new THREE.HemisphereLight(0xffefdb,0x524b46,2.3));const light=new THREE.DirectionalLight(0xffeed8,2.3);light.position.set(4,8,6);scene.add(light);camera=new THREE.OrthographicCamera(-1,1,1,-1,.01,1000);}
  releaseCopy();copy=next;observed=model;scene.add(copy);copy.rotation.y=.35;copy.updateMatrixWorld(true);
  const box=new THREE.Box3().setFromObject(copy),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3());height=Math.max(1,size.y)*1.12;camera.position.set(center.x,center.y,center.z+50);camera.lookAt(center);draw();
 };
 const interval=setInterval(poll,200);resize.observe(host);observer.observe(document.body,{childList:true,subtree:true});
 // A newly built panel can be attached immediately after this helper returns.
 if(host.isConnected)poll();
}

/* Render the same base role models used by the PC scene on the role screen. */
const bridgeRolePreviewState114={request:0,key:'',host:null,renderer:null,scene:null,camera:null,model:null,mixer:null,raf:0,last:0,height:1,fit:1,resizeInstalled:false,width:0,heightPx:0};
const bridgeRolePreviewDisposeModel114=root=>{
  if(!root)return;
  root.traverse(node=>{
    node.geometry?.dispose();
    const materials=node.material?(Array.isArray(node.material)?node.material:[node.material]):[];
    for(const material of materials){
      for(const value of Object.values(material))if(value?.isTexture)value.dispose();
      material.dispose();
    }
  });
};
function bridgeRolePreviewDispose114(){
  const p=bridgeRolePreviewState114;
  p.request++;if(p.raf)cancelAnimationFrame(p.raf);p.raf=0;p.mixer?.stopAllAction();p.mixer=null;
  if(p.resizeInstalled){window.removeEventListener('resize',bridgeRolePreviewResize114);p.resizeInstalled=false;}
  if(p.model){p.scene?.remove(p.model);bridgeRolePreviewDisposeModel114(p.model);p.model=null;}
  p.renderer?.dispose();p.renderer?.domElement?.remove();p.renderer=null;p.scene=null;p.camera=null;p.host=null;p.key='';p.width=0;p.heightPx=0;
}
function bridgeRolePreviewClearModel114(){
  const p=bridgeRolePreviewState114;
  if(p.raf)cancelAnimationFrame(p.raf);p.raf=0;p.mixer?.stopAllAction();p.mixer=null;
  if(p.model){p.scene?.remove(p.model);bridgeRolePreviewDisposeModel114(p.model);p.model=null;}
}
function bridgeRolePreviewKey114(role){
  const profession=Number(role?.profession),sex=Number(role?.sex);
  const className=({1:'shennong',2:'yinyang',3:'bing'})[profession];
  if(!className)return null;
  const sexName=sex===2&&profession===1?'junior':sex===1?'female':'male';
  return className+'-'+sexName;
}
function bridgeRolePreviewResize114(){
  const p=bridgeRolePreviewState114;if(!p.host||!p.renderer||!p.camera)return;
  const width=Math.max(1,p.host.clientWidth),height=Math.max(1,p.host.clientHeight),aspect=width/height;
  if(width===p.width&&height===p.heightPx)return;
  p.width=width;p.heightPx=height;
  const halfY=Math.max(.8,p.fit*.58),halfX=halfY*aspect;
  p.renderer.setSize(width,height,false);p.camera.left=-halfX;p.camera.right=halfX;p.camera.top=halfY;p.camera.bottom=-halfY;
  p.camera.position.set(0,p.height*.46,50);p.camera.lookAt(0,p.height*.46,0);p.camera.updateProjectionMatrix();
}
function bridgeRolePreviewFrame114(){
  const p=bridgeRolePreviewState114;if(!p.renderer||!p.model||!p.host?.isConnected||phase!=='roles'){p.raf=0;return;}
  const now=performance.now();p.mixer?.update(Math.min(.05,(now-(p.last||now))/1000));p.last=now;
  p.renderer.render(p.scene,p.camera);p.raf=requestAnimationFrame(bridgeRolePreviewFrame114);
}
function bridgeRolePreview114(role){
  const host=$('bridgeRolePreview114');if(!host)return;
  const p=bridgeRolePreviewState114,key=bridgeRolePreviewKey114(role);
  if(p.host&&p.host!==host)bridgeRolePreviewDispose114();
  if(!key){p.request++;p.key='';bridgeRolePreviewClearModel114();host.replaceChildren(el('p','请选择角色查看人物模型'));return;}
  if(p.key===key&&p.host===host){
    if(p.renderer&&p.renderer.domElement.parentNode!==host){host.replaceChildren();host.append(p.renderer.domElement);bridgeRolePreviewResize114();}
    return;
  }
  p.request++;const request=p.request;p.key=key;p.host=host;bridgeRolePreviewClearModel114();host.replaceChildren(el('p','人物模型加载中…'));
  new GLTFLoader().load('characters84/'+key+'.glb',g=>{
    if(request!==p.request||p.host!==host||phase!=='roles'){bridgeRolePreviewDisposeModel114(g.scene);return;}
    if(!p.renderer){
      p.renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:false});
      p.renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,1.5));p.scene=new THREE.Scene();
      p.scene.add(new THREE.HemisphereLight(0xffefdb,0x32433f,2.4));const light=new THREE.DirectionalLight(0xffeed8,2.6);light.position.set(4,8,6);p.scene.add(light);
      p.camera=new THREE.OrthographicCamera(-1,1,1,-1,.1,1000);
      window.addEventListener('resize',bridgeRolePreviewResize114);p.resizeInstalled=true;
    }
    host.replaceChildren();if(p.renderer.domElement.parentNode!==host)host.append(p.renderer.domElement);
    if(p.model){p.scene.remove(p.model);bridgeRolePreviewDisposeModel114(p.model);}
    p.model=g.scene;p.model.traverse(node=>{if(node.isMesh)for(const material of Array.isArray(node.material)?node.material:[node.material]){material.transparent=false;material.alphaTest=.05;material.depthWrite=true;material.needsUpdate=true;}});
    const box=new THREE.Box3().setFromObject(p.model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3());
    p.model.position.x-=center.x;p.model.position.y-=box.min.y;p.model.position.z-=center.z;p.model.scale.setScalar(.8);p.model.rotation.y=Math.PI;
    p.height=Math.max(1,size.y*.8);p.fit=p.height;p.scene.add(p.model);const idle=g.animations?.find(clip=>clip?.name==='Game 0001')??g.animations?.[0];p.mixer=idle?new THREE.AnimationMixer(p.model):null;if(p.mixer)p.mixer.clipAction(idle).play();p.last=performance.now();p.width=0;p.heightPx=0;bridgeRolePreviewResize114();if(!p.raf)p.raf=requestAnimationFrame(bridgeRolePreviewFrame114);
  },undefined,()=>{if(request===p.request&&p.host===host)host.replaceChildren(el('p','人物模型暂不可用'));});
}

