function bridgeBagGrid114(body,grid,items,capacity=40,compact=false){
 const slots=new Map(),extra=[];
 // A swap changes an item's pack, not its insertion order in the server map.
 // Filtered views must follow physical bag slots too, so the returned item
 // occupies the cell of the equipment just worn instead of moving to the end.
 const bagSlot=item=>item.slot!=null&&Number.isInteger(Number(item.slot))&&Number(item.slot)>=0&&Number(item.slot)<512?Number(item.slot):512;
 const ordered=compact?[...items].sort((a,b)=>bagSlot(a)-bagSlot(b)):items;
 for(const [index,item] of ordered.entries()){
  const slot=compact?index:Number(item.slot);
  if((compact||item.slot!=null)&&Number.isInteger(slot)&&slot>=0&&slot<512&&!slots.has(slot))slots.set(slot,item);
  else extra.push(item);
 }
 const reported=Number(capacity);
 const size=Math.max(40,compact?items.length:Number.isInteger(reported)&&reported>0?
  Math.min(reported,512):40,...[...slots.keys()].map(slot=>slot+1));
 for(let slot=0;slot<size;slot++){
  const item=slots.get(slot);
  if(item)grid.append(bridgeBagCell114(body,item));
  else {const empty=el('span',undefined,'emptyBag111');empty.setAttribute('aria-label',`空格 ${slot+1}`);grid.append(empty);}
 }
 for(const item of extra)grid.append(bridgeBagCell114(body,item));
}
