 if(!bridgeNoviceBeaconNotice117){const node=document.createElement('section'),text=document.createElement('span'),cancel=document.createElement('button');
  node.id='noviceBeacon117';node.setAttribute('aria-live','polite');
  node.style.cssText='position:fixed;left:50%;top:12px;transform:translateX(-50%);z-index:204;max-width:calc(100vw - 24px);box-sizing:border-box;display:none;align-items:center;gap:10px;padding:8px 12px;background:#11160ff0;border:1px solid #a88435;color:#f2dfb0;font-size:14px;';
  cancel.textContent='取消前往';cancel.style.cssText='min-height:36px;padding:4px 10px;';
  cancel.onclick=()=>{if(bridgeNoviceBeaconTravel117){bridgeNoviceBeaconTravel117=null;act({kind:'navigate_stop'});}node.style.display='none';};
  node.append(text,cancel);document.body.append(node);bridgeNoviceBeaconNotice117={node,text,cancel};}
 const notice=bridgeNoviceBeaconNotice117;notice.mode=mode;notice.text.textContent=message;notice.cancel.hidden=mode!=='travel';notice.node.style.display=message?'flex':'none';
