async function directLauncherRequest114(body={}){
 if(!window.Lab?.request95)throw Error('直连区服列表必须在 APK 原生环境读取');
 return new Promise((resolve,reject)=>{
  const id=++nativeId,timer=setTimeout(()=>{native.delete(id);reject(Error('区服列表读取超时'));},12000);
  native.set(id,{resolve,reject,timer,route:'/direct/zones',started:performance.now()});
  window.Lab.request95(id,$('endpoint').value.replace(/\/$/,''),'/direct/zones','','',JSON.stringify(body));
 });
}
function parseLauncherZones114(text){
 const zones=[],seen=new Set();let server=false;
 for(const raw of String(text??'').split(/\r?\n/)){
  const line=raw.trim();if(!line||line.startsWith(';'))continue;
  if(line.startsWith('[')&&line.endsWith(']')){server=line.slice(1,-1).trim().toLowerCase()==='server';continue;}
  if(!server||!line.includes('='))continue;
  const value=line.slice(line.indexOf('=')+1).trim().replace(/^['\"`]|['\"`]$/g,'');
  const fields=value.split('|').map(v=>v.trim());if(fields.length<7)continue;
  const category=fields[0],name=fields[1],serverName=fields[2],host=fields[3];
  const port=Number(fields[4]),zoneId=Number(fields[5]),gamePort=fields[7]?Number(fields[7]):0;
  if(!name||!serverName||!host||!Number.isInteger(port)||port<1||port>65535||
     !Number.isInteger(zoneId)||!Number.isInteger(gamePort)||gamePort<0||gamePort>65535||/[\s\\/]/.test(host))continue;
  const id=`${serverName}|${host}|${port}`;if(seen.has(id))continue;seen.add(id);
  const row={id,name,serverName,category,host,port,zoneId,gamePort};
  if(fields[9]&&fields[10]&&Number.isInteger(Number(fields[10]))&&Number(fields[10])>0&&Number(fields[10])<=65535)
   {row.gatewayHost=fields[9];row.gatewayPort=Number(fields[10]);}
  zones.push(row);
 }
 return zones;
}
async function directZoneCatalogue114(){
 const result=await directLauncherRequest114({});
 const body=result?.configText??result?.config;
 const zones=parseLauncherZones114(body);
 if(!zones.length)throw Error('区服列表为空或格式不受支持');
 return {zones};
}
async function loadZoneCatalogue114(){
 const group=$('serverZones114'),select=$('serverZone');
 if(!group||!select)return;
 group.textContent='正在读取区服列表…';
 const result=$('endpoint').value.startsWith('zg+tcp://')?await directZoneCatalogue114():await crossplay95('/catalogue',{});
 const zones=Array.isArray(result?.zones)?result.zones.filter(z=>z&&typeof z.id==='string'&&z.id&&typeof z.name==='string'&&z.name):[];
 if(!zones.length)throw Error('网关没有可用区服');
 const key='zg.pc.lastZone114:'+($('endpoint')?.value??'');
 let saved='';try{saved=localStorage.getItem(key)||'';}catch{}
 const selected=zones.some(z=>z.id===saved)?saved:zones[0].id;
 const buttons=[];
 group.replaceChildren(...zones.map(z=>{
  const b=document.createElement('button');b.type='button';b.setAttribute('role','radio');b.setAttribute('aria-checked','false');b.dataset.zone114=z.id;b.textContent=z.name;buttons.push(b);return b;
 }));
 select.replaceChildren(...zones.map(z=>{const o=document.createElement('option');o.value=z.id;o.textContent=z.name;return o;}));
 const choose=value=>{if(!zones.some(z=>z.id===value))return;select.value=value;for(const b of buttons)b.setAttribute('aria-checked',String(b.dataset.zone114===value));try{localStorage.setItem(key,value);}catch{}};
 for(const b of buttons)b.onclick=()=>choose(b.dataset.zone114);
 choose(selected);
}$('shared95').onchange=async()=>{if($('shared95').checked){const p=await fetch('server-profile95.json').then(r=>r.json());const direct=p.role==='direct-game'&&p.transport==='direct-tcp';$('endpoint').value=(direct?'zg+tcp://':'zg+tls://')+p.host+':'+p.port;await loadZoneCatalogue114();}else $('endpoint').value=window.Lab?'http://127.0.0.1:27150':location.origin;};

