// Native instance questions are shown verbatim for the player's manual choice.
let bridgeInstanceAnswerBox114=null,bridgeInstanceAnswerScope114=null;
const bridgeInstanceAnswerRetired114=new Set();

function bridgeInstanceAnswerRetire114(key){
 if(typeof key!=='string'||!key)return;
 bridgeInstanceAnswerRetired114.add(key);
 if(bridgeInstanceAnswerRetired114.size>256)
  bridgeInstanceAnswerRetired114.delete(bridgeInstanceAnswerRetired114.values().next().value);
}

