function bridgeInstanceAnswerWorld114(){
 return typeof world!=='undefined'&&world&&typeof world==='object'?world:null;
}

function bridgeInstanceAnswerProjection114(source){
 const frame=bridgeInstanceAnswerWorld114(),projection=value=>({row:value?.instanceAnswer??null,
  revision:Number.isInteger(value?.instanceAnswerRevision)&&value.instanceAnswerRevision>=0?value.instanceAnswerRevision:null});
 if(source==='world')return projection(frame);
 if(source==='state')return projection(state);
 const fromState=projection(state),fromWorld=projection(frame);
 if(!frame||!Object.prototype.hasOwnProperty.call(frame,'instanceAnswer'))return fromState;
 // HTTP state and world frames can arrive in either order. A native question
 // revision orders both projections, including null/close, within this epoch.
 if(fromState.revision!==null&&(fromWorld.revision===null||fromState.revision>fromWorld.revision))return fromState;
 // Keep the previous world preference for legacy unversioned offline fixtures.
 return fromWorld;
}

function bridgeInstanceAnswerRead114(){
 return bridgeInstanceAnswerScope114?.row??null;
}

function bridgeInstanceAnswerNow114(){
 const frame=bridgeInstanceAnswerWorld114();
 return Math.max(Date.now(),Number.isFinite(frame?.time)?frame.time:0);
}

function bridgeInstanceAnswerObserve114(source='auto'){
 const owner=state?.character?.id,generation=epoch,previous=bridgeInstanceAnswerBox114;
 if(phase!=='game'||!owner){
  previous?.dispose(true);bridgeInstanceAnswerScope114=null;return;
 }
 if(bridgeInstanceAnswerScope114&&
   (bridgeInstanceAnswerScope114.owner!==owner||bridgeInstanceAnswerScope114.generation!==generation)){
  previous?.dispose(true);
  bridgeInstanceAnswerScope114={owner,generation,source,attempted:new Set(),revision:null,row:null};
  // The previous observation belongs to another owner/connection. Its buttons
  // are invalid immediately; a subsequent fresh observation may show a new key.
  return;
 }
 if(!bridgeInstanceAnswerScope114)
  bridgeInstanceAnswerScope114={owner,generation,source,attempted:new Set(),revision:null,row:null};
 const scope=bridgeInstanceAnswerScope114;
 const nextSource=['world','state'].includes(source)?source:'auto',projection=bridgeInstanceAnswerProjection114(nextSource);
 if(scope.revision!==null&&(projection.revision===null||projection.revision<scope.revision)){
  // An older frame must not retire the current key, disable its manual choice
  // or replace a newer submitted projection. Its countdown still needs ticks.
  previous?.render();return;
 }
 scope.source=nextSource;scope.row=projection.row;
 if(projection.revision!==null)scope.revision=projection.revision;
 const row=scope.row;
 if(!row||typeof row.questionKey!=='string'||!row.questionKey||
   bridgeInstanceAnswerRetired114.has(row.questionKey)){
  previous?.dispose(true);return;
 }
 if(previous&&previous.owner===owner&&previous.generation===generation&&
   previous.key===row.questionKey&&previous.overlay.isConnected){
  previous.row=row;previous.render();return;
 }
 previous?.dispose(true);bridgeInstanceAnswerStyle114();
 const opening={owner,generation,key:row.questionKey,row,timer:null,pending:false,failure:false};
 const make=(tag,cls,text)=>{
  const node=document.createElement(tag);if(cls)node.className=cls;
  if(text!==undefined)node.textContent=text;return node;
 };
 const overlay=make('div','bridgeInstanceAnswer114'),card=make('section','bridgeInstanceAnswerCard114'),
  heading=make('header','bridgeInstanceAnswerHeading114'),title=make('h2','', '副本答题'),
  countdown=make('span','bridgeInstanceAnswerCountdown114'),subject=make('p','bridgeInstanceAnswerSubject114'),
  choices=make('div','bridgeInstanceAnswerOptions114'),status=make('p','bridgeInstanceAnswerStatus114');
 card.setAttribute('role','dialog');card.setAttribute('aria-label','副本答题');card.setAttribute('aria-modal','false');
 status.setAttribute('aria-live','polite');heading.append(title,countdown);
 card.append(heading,subject,choices,status);overlay.append(card);opening.overlay=overlay;
 const contextCurrent=()=>bridgeInstanceAnswerBox114===opening&&overlay.isConnected&&
  phase==='game'&&epoch===generation&&state?.character?.id===owner&&bridgeInstanceAnswerScope114===scope;
 const current=()=>contextCurrent()&&bridgeInstanceAnswerRead114(scope.source)?.questionKey===opening.key&&
  !bridgeInstanceAnswerRetired114.has(opening.key);
 const buttons=[];
 const setText=(node,text)=>{if(node.textContent!==text)node.textContent=text;};
 const optionsFor=live=>Array.isArray(live?.options)?live.options:[];
 const canAnswer=(live,index)=>current()&&!scope.attempted.has(opening.key)&&!opening.pending&&
  !live.submitted&&live.phase==='ready'&&Number.isFinite(live.expiresAt)&&
  live.expiresAt>bridgeInstanceAnswerNow114()&&
  optionsFor(live).filter(option=>option?.index===index&&typeof option.text==='string'&&option.text.length>0).length===1;
 const submit=async index=>{
  const live=bridgeInstanceAnswerRead114(scope.source);
  if(!canAnswer(live,index))return;
  // Retain an attempted key even if HTTP fails. A user choice is never replayed
  // by mutate(), a timer, a redraw, a revision update or a second click.
  scope.attempted.add(opening.key);opening.pending=true;opening.failure=false;opening.render();
  try{
   const result=await request('/action',{key:crypto.randomUUID(),revision:state.revision,
    action:{type:'instance_answer',questionKey:opening.key,answerIndex:index}});
   if(!current())return;
   if(result?.state&&result.state.character?.id===owner&&Number(result.state.revision)>=Number(state.revision)){
    apply(result.state);
    if(contextCurrent())bridgeInstanceAnswerObserve114('state');
   }
  }catch(failure){
   if(current()){opening.failure=true;opening.render();}
  }finally{
   opening.pending=false;if(current())opening.render();
  }
 };
 for(let index=1;index<=6;index++){
  const choice=make('button',''),letter=make('span','bridgeInstanceAnswerLetter114',String.fromCharCode(64+index)+'：'),
   text=make('span','bridgeInstanceAnswerText114');
  choice.type='button';choice.dataset.answerIndex=String(index);
  choice.append(letter,text);choice.addEventListener('click',()=>void submit(index));
  choices.append(choice);buttons.push({choice,text,index});
 }
 for(const event of ['pointerdown','pointerup','click','keydown','keyup'])
  card.addEventListener(event,event=>event.stopPropagation());
 opening.dispose=retire=>{
  if(retire)bridgeInstanceAnswerRetire114(opening.key);
  if(opening.timer!==null)clearTimeout(opening.timer);opening.timer=null;
  overlay.remove();if(bridgeInstanceAnswerBox114===opening)bridgeInstanceAnswerBox114=null;
 };
 opening.render=()=>{
  if(!current()){opening.dispose(true);return;}
  const live=bridgeInstanceAnswerRead114(scope.source);opening.row=live;
  const seconds=Number.isFinite(live.expiresAt)?Math.max(0,Math.ceil((live.expiresAt-bridgeInstanceAnswerNow114())/1000)):0,
   expired=live.phase==='expired'||seconds<=0,
   submitted=live.submitted||live.phase==='submitted'||scope.attempted.has(opening.key);
  setText(subject,typeof live.subject==='string'?live.subject:'');
  setText(countdown,expired?'时间已到':`剩余 ${seconds} 秒`);
  setText(status,expired?'答题时间已到，等待服务器关闭。':opening.failure?
   '提交结果未确认，等待服务器更新。':opening.pending?'正在提交答案，等待服务器确认…':
   submitted?'答案已提交，等待服务器关闭。':'请阅读题目并选择答案。');
  for(const button of buttons){
   const options=optionsFor(live).filter(option=>option?.index===button.index),option=options.length===1?options[0]:null;
   setText(button.text,typeof option?.text==='string'?option.text:'');
   button.choice.disabled=expired||!canAnswer(live,button.index);
  }
  if(opening.timer===null)opening.timer=setTimeout(()=>{
   opening.timer=null;if(contextCurrent())bridgeInstanceAnswerObserve114(scope.source);
  },200);
 };
 bridgeInstanceAnswerBox114=opening;document.body.append(overlay);opening.render();
}


// A canvas event (including the Labels110 synthetic forward) is allowed only
// where the visible UI currently exposes a real scene surface.
let bridgeScenePointerTraceCount114=0;
function bridgeScenePointerAllowed114(event,source='world'){
 const x=event?.clientX,y=event?.clientY;
 const shown=node=>{
  if(!node?.isConnected||node.hidden||node.classList.contains('hidden'))return false;
  const style=getComputedStyle(node);
  return style.display!=='none'&&style.visibility!=='hidden'&&style.visibility!=='collapse'&&node.getClientRects().length>0;
 };
 const panel=document.getElementById('panel'),panelVisible=shown(panel),
  rect=panelVisible?panel.getBoundingClientRect():null;
 let top=null,allowed=false;
 if(typeof phase!=='undefined'&&phase==='game'&&Number.isFinite(x)&&Number.isFinite(y)&&!panelVisible){
  const track=document.getElementById('questTrack'),r=shown(track)?track.getBoundingClientRect():null,
   questHit=!!r&&r.width>0&&r.height>0&&x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom;
  top=document.elementFromPoint(x,y);
  allowed=!questHit&&!!top&&(top===document.getElementById('world')||top===document.getElementById('labelsCanvas110'));
 }else if(Number.isFinite(x)&&Number.isFinite(y))top=document.elementFromPoint(x,y);
 if((globalThis.__zgCombatTrace114===true||globalThis.__zgCombatTrace===true)&&bridgeScenePointerTraceCount114<256){
  bridgeScenePointerTraceCount114++;
  const node=value=>({id:typeof value?.id==='string'?value.id.slice(0,64):'',tag:typeof value?.tagName==='string'?value.tagName.slice(0,20):''});
  const row={event:'scene_pointer',kind:'scene_pointer',at:Date.now(),source:source==='labels'?'labels':'world',
   x:Number.isFinite(x)?Math.round(x*100)/100:null,y:Number.isFinite(y)?Math.round(y*100)/100:null,
   target:node(event?.target),top:node(top),panel:{visible:panelVisible,
    ...(rect?{left:rect.left,top:rect.top,right:rect.right,bottom:rect.bottom}: {})},allowed};
  try{console.info('[ZG_COMBAT] '+JSON.stringify(row));}catch{}
 }
 return allowed;
}
globalThis.bridgeScenePointerAllowed114=bridgeScenePointerAllowed114;

